"""Original B1 grammar, vocabulary and writing practice material.

The questions and tasks are training examples, not official Cambridge papers.
"""


def _question(number, topic, prompt, options, answer, explanation):
    return {
        "id": f"grammar_{number:03d}",
        "skill": "Grammar",
        "topic": topic,
        "prompt": prompt,
        "options": options,
        "answer": answer,
        "explanation": explanation,
    }


GRAMMAR = [
    _question(1, "Present tenses", "My sister usually _____ to school by bus.", ["go", "goes", "is going", "going"], "goes", "Use the present simple for a routine. Add -s with he, she or it."),
    _question(2, "Present tenses", "Be quiet! I _____ to an important announcement.", ["listen", "listens", "am listening", "listened"], "am listening", "Use the present continuous for something happening now."),
    _question(3, "Present tenses", "How often _____ your brother play tennis?", ["do", "does", "is", "has"], "does", "Present simple questions with he or she use does and the base form of the verb."),
    _question(4, "Present tenses", "I _____ what you mean. Could you explain it again?", ["am not understanding", "don't understand", "not understand", "doesn't understand"], "don't understand", "Understand is normally a state verb, so use the present simple here."),
    _question(5, "Past tenses", "We _____ a great film at the cinema last Saturday.", ["see", "have seen", "saw", "seen"], "saw", "Last Saturday is a finished past time, so use the past simple."),
    _question(6, "Past tenses", "I _____ dinner when my friend called.", ["cook", "have cooked", "was cooking", "am cooking"], "was cooking", "The past continuous describes the activity in progress when another event happened."),
    _question(7, "Past tenses", "While we _____ home, it started to rain.", ["were walk", "were walking", "have walked", "are walking"], "were walking", "Use the past continuous for the background activity that was in progress."),
    _question(8, "Past tenses", "When I was younger, I _____ a bike to school every day.", ["used to ride", "use to ride", "was used ride", "used riding"], "used to ride", "Used to plus the base verb describes a past habit that has changed."),
    _question(9, "Present perfect", "I _____ my homework, so I can go out now.", ["finish", "am finishing", "have finished", "was finishing"], "have finished", "The present perfect links a completed action to its present result."),
    _question(10, "Present perfect", "Marta has lived in this town _____ 2021.", ["for", "since", "during", "from"], "since", "Use since with the starting point of a period that continues now."),
    _question(11, "Present perfect", "We haven't visited the new museum _____.", ["already", "yet", "since", "just"], "yet", "Yet commonly appears at the end of negative present perfect sentences."),
    _question(12, "Present perfect", "Have you ever _____ a horse?", ["ride", "rode", "ridden", "riding"], "ridden", "The present perfect uses have or has plus the past participle: ridden."),
    _question(13, "Future forms", "Look at those dark clouds! It _____ rain.", ["is going to", "will to", "would", "was going"], "is going to", "Use going to for a prediction based on evidence you can see."),
    _question(14, "Future forms", "I've booked the tickets. We _____ to Paris next Friday.", ["fly yesterday", "are flying", "have flown", "were flying"], "are flying", "Use the present continuous for a future arrangement with a fixed time."),
    _question(15, "Future forms", "That bag looks heavy. I _____ help you carry it.", ["am helping yesterday", "will", "will to", "have"], "will", "Use will for an offer made at the moment of speaking."),
    _question(16, "Future forms", "The train _____ at 8.15 tomorrow morning, according to the timetable.", ["leave", "leaves", "left", "has left"], "leaves", "Use the present simple for a fixed timetable, including future departures."),
    _question(17, "Modals", "You _____ wear a seat belt when you travel in a car. It's the law.", ["might", "must", "could", "would"], "must", "Must expresses a strong obligation, such as a legal requirement."),
    _question(18, "Modals", "Complete with the phrase meaning 'it is not necessary': You _____ buy a ticket. Entry to the museum is free.", ["mustn't", "don't have to", "can't", "shouldn't"], "don't have to", "Don't have to means there is no obligation. Mustn't means something is forbidden."),
    _question(19, "Modals", "You look tired. You _____ go to bed earlier tonight.", ["should", "mustn't", "may not", "needn't"], "should", "Should is used to give advice."),
    _question(20, "Modals", "I _____ swim when I was six, but now I swim every week.", ["can't", "couldn't", "mustn't", "shouldn't"], "couldn't", "Could and couldn't describe general ability in the past."),
    _question(21, "Conditionals", "If it rains tomorrow, we _____ indoors.", ["stayed", "would stay", "will stay", "had stayed"], "will stay", "The first conditional uses if plus present simple, then will plus the base verb."),
    _question(22, "Conditionals", "If I _____ more free time, I would learn to play the guitar.", ["have", "had", "will have", "am having"], "had", "The second conditional uses the past simple for an imagined present situation."),
    _question(23, "Conditionals", "If you heat ice, it _____.", ["melts", "will melted", "would melting", "has melt"], "melts", "Use the zero conditional, with two present simple verbs, for a general fact."),
    _question(24, "Conditionals", "Unless you hurry, you _____ the bus.", ["missed", "would miss", "will miss", "had missed"], "will miss", "Unless means if not. Use the present simple after unless and will in the result."),
    _question(25, "Comparatives", "This exercise is _____ than the first one.", ["easy", "easiest", "easier", "more easy"], "easier", "For a short adjective ending in -y, change -y to -ier in the comparative."),
    _question(26, "Comparatives", "It was _____ journey I have ever made.", ["the longest", "longer", "most long", "as long"], "the longest", "Use the plus a superlative to compare one thing with all the others."),
    _question(27, "Comparatives", "My new phone is _____ expensive as yours.", ["so", "as", "than", "more"], "as", "As plus adjective plus as describes two things with the same quality."),
    _question(28, "Comparatives", "Today's weather is _____ than yesterday's.", ["good", "best", "better", "well"], "better", "Better is the irregular comparative form of good."),
    _question(29, "Articles and quantifiers", "We don't have _____ milk left in the fridge.", ["many", "much", "a few", "an"], "much", "Milk is uncountable. Use much, especially in negatives and questions."),
    _question(30, "Articles and quantifiers", "There are _____ apples in the bowl, so you can take one.", ["a little", "much", "a few", "any"], "a few", "A few means a small positive number and is used with plural countable nouns."),
    _question(31, "Articles and quantifiers", "I bought _____ umbrella because it was raining.", ["a", "an", "the every", "many"], "an", "Use an before a singular countable noun that begins with a vowel sound."),
    _question(32, "Articles and quantifiers", "There isn't _____ sugar in this tea. Could you add some?", ["enough", "too many", "a few", "many"], "enough", "Enough before a noun means a sufficient amount. Sugar is uncountable."),
    _question(33, "Prepositions", "My birthday is _____ 12 June.", ["in", "on", "at", "by"], "on", "Use on with a specific day or date."),
    _question(34, "Prepositions", "We arrived _____ the airport two hours before our flight.", ["to", "on", "at", "into"], "at", "Use arrive at for a place such as an airport or station; use arrive in for a city or country."),
    _question(35, "Prepositions", "I'm interested _____ learning another language.", ["at", "on", "in", "for"], "in", "The adjective interested is followed by in and a noun or -ing form."),
    _question(36, "Prepositions", "Who does this jacket belong _____?", ["to", "with", "for", "at"], "to", "The verb belong is followed by to when you say who owns something."),
    _question(37, "Verb patterns", "I enjoy _____ books about travel.", ["read", "to read", "reading", "to reading"], "reading", "Enjoy is followed by a verb in the -ing form."),
    _question(38, "Verb patterns", "They decided _____ a new sports club.", ["join", "joining", "to join", "to joining"], "to join", "Decide is followed by to plus the base form of the verb."),
    _question(39, "Verb patterns", "Please let me _____ you with your homework.", ["help", "to help", "helping", "helped"], "help", "Let plus an object is followed by the base form without to."),
    _question(40, "Verb patterns", "I'm looking forward to _____ you next week.", ["see", "to see", "seeing", "saw"], "seeing", "In look forward to, to is a preposition, so it is followed by an -ing form."),
    _question(41, "Relative clauses", "The woman _____ lives next door is a doctor.", ["who", "which", "where", "whose"], "who", "Use who to introduce a relative clause about a person."),
    _question(42, "Relative clauses", "This is the café _____ we met last summer.", ["who", "which", "where", "whose"], "where", "Use where for a place in which something happened."),
    _question(43, "Relative clauses", "I have a friend _____ father works at the airport.", ["who", "whose", "which", "where"], "whose", "Whose expresses possession: the father belongs to the friend's family."),
    _question(44, "Relative clauses", "The book _____ you lent me was very interesting.", ["where", "whose", "who", "which"], "which", "Use which for a thing, such as a book."),
    _question(45, "Passive voice", "These bicycles _____ in Germany.", ["make", "are made", "made", "are making"], "are made", "The present simple passive uses am, is or are plus the past participle."),
    _question(46, "Passive voice", "The old bridge _____ in 1920.", ["built", "was built", "is building", "has building"], "was built", "The past simple passive uses was or were plus the past participle."),
    _question(47, "Passive voice", "English _____ in many countries around the world.", ["speaks", "is spoken", "is speaking", "has speak"], "is spoken", "Use the passive when the subject receives the action: English is spoken by people."),
    _question(48, "Passive voice", "The windows _____ yesterday afternoon.", ["were cleaned", "are cleaning", "have clean", "was cleaned"], "were cleaned", "Yesterday requires the past simple. The plural subject windows takes were."),
]


def _card(number, word, meaning, example, topic):
    return {
        "id": f"vocabulary_{number:03d}",
        "word": word,
        "meaning": meaning,
        "example": example,
        "topic": topic,
    }


